from research_helpers import *
a=ev('https://static.cninfo.com.cn/finalpage/2025-04-28/1223349316.PDF','Yichang HEC Changjiang 2024 issuer annual report: actual insulin sales, core formulations and February/March 2025 HCV approvals. Parent development pipeline is not automatically the old listed subsidiary portfolio.')
b=ev('https://www.hecpharm.com/products.html','Current successor-group catalogue corroborates HCV and insulin brands. Chinese version includes newer HCV agents omitted from English page.')
c=ev('https://www.hec-changjiang.com/en/product.aspx?ProductsCateID=53&parid=53','Legacy issuer core-product index includes Xinhaining and Xining; listing alone not current sales confirmation.')
d=ev('https://hecpharm.com/about.html','Official corporate history reports absorption merger of HEC Changjiang in 2025. Historical company relationships retained; detailed legal transfer date requires reconciliation.')
rows=[('Kewei granules','Oseltamivir-phosphate granule formulation.'),('Kewei capsules','Oseltamivir-phosphate capsule formulation.'),('Oumeining','Telmisartan tablets.'),('Ertongshu','Benzbromarone tablets.'),('Dongweien','Emitasvir-phosphate capsules.'),('Yibilin R','Recombinant human-insulin injection.'),('Yibilin 30','Mixed protamine human-insulin injection, 30R.'),('Yibigan','Insulin-glargine injection.'),('HEC insulin aspart injection','Insulin-aspart injection.'),('HEC insulin aspart 30 injection','Biphasic insulin-aspart injection.'),('Dongweizhuo','Natantasvir-phosphate capsules.'),('Dongyinghe','Emitasbuvir tablets.')]
rows=[(n,('HCV capsule formulation (磷酸萘坦司韦).' if n=='Dongweizhuo' else desc.replace('Emitasbuvir','Encofosbuvir'))) for n,desc in rows]
products=[p(n,desc,a,'commercial',typ='product',roles=['commercial_partner'],territory='China',evidence=[a,b,d]) for n,desc in rows]
products += [p(n,desc,c,'unknown',typ='product',roles=['commercial_partner'],territory='China',evidence=[c,d]) for n,desc in [('Xinhaining','Amlodipine tablets; historical company catalogue.'),('Xining','Cetirizine product; historical company catalogue.')]]
co=dict(company_id='cmp_07ffdba1-373c-490f-be58-e68cfe80b07c',products=products,evidence=[a,b,c,d],status='partial',coverage_note='Fourteen identifiable branded/formulated products from issuer report and catalogue. Commercial status reflects continuing product availability, not survival of the former listed entity after 2025 absorption merger. Partial: exact legal succession and relationship end dates, full 36-entry historical catalogue, other generics, Olorigliflozin current disposition and licensed development rights require further review. No automatic attribution of successor parent entire pipeline or third-party combination drugs.')
(out/'batch-0280.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
